const CASEIMGS={"l2":"data:image/jpeg;base64,","l3":"data:image/jpeg;base64,","l4":"data:image/jpeg;base64,","l5":"data:image/jpeg;base64,","l6":"data:image/jpeg;base64,","l7":"data:image/jpeg;base64,","l8":"data:image/jpeg;base64,","w2":"data:image/jpeg;base64,","ab4":"data:image/jpeg;base64,","ab5":"data:image/jpeg;base64,","ab6":"data:image/jpeg;base64,","ab7":"data:image/jpeg;base64,","ab8":"data:image/jpeg;base64,","ab9":"data:image/jpeg;base64,","ab10":"data:image/jpeg;base64,","wa3":"data:image/jpeg;base64,","wa1":"data:image/jpeg;base64,"};

// LOADER
let p=0;const lp=document.getElementById('ldp');
const lt=setInterval(()=>{p=Math.min(p+Math.random()*18,99);lp.textContent=Math.round(p)+'%';if(p>=99)clearInterval(lt);},100);
window.addEventListener('load',()=>{lp.textContent='100%';setTimeout(()=>document.getElementById('loader').classList.add('done'),300);});

// TYPING
const roles=['Logo Designer','Brand Identity','Social Media Design','Creative Designer'];
let ri=0,ci=0,d=false,el=document.getElementById('role');
function type(){const c=roles[ri];if(!d){el.textContent=c.slice(0,++ci);if(ci===c.length){d=true;setTimeout(type,2000);return;}}else{el.textContent=c.slice(0,--ci);if(ci===0){d=false;ri=(ri+1)%roles.length;}}setTimeout(type,d?50:90);}
setTimeout(type,2400);

// CURSOR
if(!('ontouchstart' in window)){
  const cd=document.querySelector('.c-dot'),cr=document.querySelector('.c-ring');
  let mx=0,my=0,rx=0,ry=0;
  document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cd.style.left=mx+'px';cd.style.top=my+'px';});
  (function a(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;cr.style.left=rx+'px';cr.style.top=ry+'px';requestAnimationFrame(a);})();
  document.querySelectorAll('a,button,.pc,.cert-card,.stat-row,.sk,.edu-card').forEach(el=>{
    el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
    el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
  });
}else{document.getElementById('cur').style.display='none';}

// NAV
window.addEventListener('scroll',()=>{
  document.getElementById('nav').classList.toggle('sc',scrollY>50);
  document.getElementById('prog').style.width=(scrollY/(document.body.scrollHeight-innerHeight)*100)+'%';
  document.getElementById('btt').classList.toggle('show',scrollY>500);
});

// MOBILE MENU
function tmenu(){document.getElementById('ham').classList.toggle('o');document.getElementById('mob').classList.toggle('o');}

// REVEAL
const io=new IntersectionObserver(entries=>{
  entries.forEach(e=>{
    if(!e.isIntersecting)return;
    e.target.classList.add('vis');io.unobserve(e.target);
  });
},{threshold:.1});
document.querySelectorAll('.rv,.rv-l,.rv-r').forEach(el=>io.observe(el));

// SKILL BARS
const skIO=new IntersectionObserver(([e])=>{
  if(!e.isIntersecting)return;
  e.target.querySelectorAll('.sk').forEach((item,i)=>{
    const bar=item.querySelector('.sk-fill');
    if(bar)setTimeout(()=>bar.style.width=item.dataset.pct+'%',150+i*80);
  });
  skIO.unobserve(e.target);
},{threshold:.1});
const sg=document.getElementById('skgrid');if(sg)skIO.observe(sg);

// FILTER
document.querySelectorAll('.f').forEach(btn=>{
  btn.addEventListener('click',()=>{
    document.querySelectorAll('.f').forEach(b=>b.classList.remove('on'));
    btn.classList.add('on');
    const f=btn.dataset.filter;
    document.querySelectorAll('.pc').forEach(c=>{
      const show=f==='all'||c.dataset.cat===f;
      c.style.display=show?'':'none';
    });
  });
});

// MODAL
function openCase(id){
  const d=CASES[id],img=CASEIMGS[id];
  document.getElementById('m-img').src=img;
  document.getElementById('m-tag').textContent=d.tag;
  document.getElementById('m-client').textContent=d.client;
  document.getElementById('m-year').textContent=d.year;
  document.getElementById('m-tools').textContent=d.tools;
  document.getElementById('m-title').textContent=d.title;
  document.getElementById('m-desc').textContent=d.desc;
  document.getElementById('modal').classList.add('open');
  document.body.style.overflow='hidden';
}
function closeModal(){document.getElementById('modal').classList.remove('open');document.body.style.overflow='';}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});

// FORM
function doForm(e){
  e.preventDefault();const b=document.getElementById('fsub');
  b.textContent='Sending...';b.disabled=true;
  setTimeout(()=>{b.textContent='Sent ✓';b.style.background='#16a34a';
    setTimeout(()=>{b.textContent='Send Message →';b.style.background='';b.disabled=false;e.target.reset();},2500);
  },900);
}

